 //==================================================================================================
 // Helper spec functions
 //==================================================================================================

 /// Sum of elements in `s` from index `from` (inclusive) to the end.
 pub open spec fn seq_sum_from(s: Seq<int>, from: int) -> int
     decreases (if from < s.len() { s.len() - from } else { 0 }),
 {
